"use client";

import * as React from "react";
import { Alert, AlertDescription, AlertTitle } from "../../components/alert/alert.js";
import {
	InputOTP,
	InputOTPGroup,
	InputOTPSlot,
} from "../../components/input-otp/input-otp.js";
import { Button } from "../../primitives/button/button.js";
import { cn } from "../../lib/utils.js";
import type { AuthAdapter, AuthOtpIntent } from "../_shared/auth-adapter.js";

export interface AuthVerifyOtpProps {
	adapter: AuthAdapter;
	/** Forwarded verbatim to adapter.verifyOtp({ code, intent }). */
	intent: AuthOtpIntent;
	/** Total number of digits in the code. Defaults to 6. */
	length?: number;
	/** Seconds the resend button stays disabled after each successful resend. */
	resendCooldownSeconds?: number;
	className?: string;
	onSuccess?: (redirect: string | undefined) => void;
}

const HEADINGS: Record<AuthOtpIntent, { title: string; description: string }> = {
	"sign-in": {
		title: "Enter your sign-in code",
		description: "We sent a 6-digit code to your email or phone. Enter it below to sign in.",
	},
	"verify-email": {
		title: "Verify your email",
		description: "Enter the 6-digit code we sent to confirm your email address.",
	},
	mfa: {
		title: "Two-factor authentication",
		description: "Enter the 6-digit code from your authenticator app.",
	},
};

/**
 * One-time-code verification page. Renders an `InputOTP` of `length` slots
 * and submits automatically when the code is full. Routes verification
 * through `adapter.verifyOtp({ code, intent })`. Optional resend button
 * calls `adapter.resendOtp({ intent })` when implemented.
 */
export function AuthVerifyOtp({
	adapter,
	intent,
	length = 6,
	resendCooldownSeconds = 30,
	className,
	onSuccess,
}: AuthVerifyOtpProps) {
	const [code, setCode] = React.useState("");
	const [submitting, setSubmitting] = React.useState(false);
	const [resending, setResending] = React.useState(false);
	const [cooldownLeft, setCooldownLeft] = React.useState(0);
	const [error, setError] = React.useState<{ code: string; message: string } | null>(null);
	// Dedup guard for the auto-submit effect.
	//
	// The effect depends on `submitting` so it can short-circuit while a
	// request is in flight. After the request resolves, `submitting` flips
	// false → the effect re-runs → the same `code` value is still full → it
	// would auto-submit again. The ref captures the value we last dispatched
	// so a second pass is a no-op. Reset back to "" on error (alongside
	// `setCode("")`) so the user can re-enter the same digits without the
	// guard short-circuiting.
	const lastSubmittedRef = React.useRef<string>("");

	React.useEffect(() => {
		if (cooldownLeft <= 0) return;
		const timer = setTimeout(() => setCooldownLeft((s) => s - 1), 1000);
		return () => clearTimeout(timer);
	}, [cooldownLeft]);

	const handleSubmit = React.useCallback(
		async (codeToSubmit: string) => {
			if (!adapter.verifyOtp) {
				console.warn(
					"[AuthVerifyOtp] adapter.verifyOtp is not implemented — wire it up before exposing the form.",
				);
				setError({
					code: "unimplemented",
					message: "Verification is currently unavailable. Please try again later.",
				});
				return;
			}
			setError(null);
			setSubmitting(true);
			try {
				const result = await adapter.verifyOtp({ code: codeToSubmit, intent });
				if (!result.ok) {
					setError(
						result.error ?? { code: "unknown", message: "Couldn't verify code." },
					);
					// Reset both the visible value and the dedup ref so the user can
					// re-enter the same digits without the effect short-circuiting.
					setCode("");
					lastSubmittedRef.current = "";
					return;
				}
				onSuccess?.(result.redirect);
			} finally {
				setSubmitting(false);
			}
		},
		[adapter, intent, onSuccess],
	);

	// Auto-submit when the code reaches full length. Guarded by a ref so the
	// effect doesn't re-fire when `submitting` flips back to false after the
	// request resolves — `setCode("")` on error already gives a fresh attempt.
	React.useEffect(() => {
		if (code.length !== length) return;
		if (submitting) return;
		if (lastSubmittedRef.current === code) return;
		lastSubmittedRef.current = code;
		void handleSubmit(code);
	}, [code, length, submitting, handleSubmit]);

	async function handleResend() {
		if (!adapter.resendOtp) {
			console.warn(
				"[AuthVerifyOtp] adapter.resendOtp is not implemented — hide the resend button or wire the method.",
			);
			setError({
				code: "unimplemented",
				message: "Resending is currently unavailable. Please try again later.",
			});
			return;
		}
		setError(null);
		setResending(true);
		try {
			const result = await adapter.resendOtp({ intent });
			if (!result.ok) {
				setError(result.error ?? { code: "unknown", message: "Couldn't resend code." });
				return;
			}
			setCooldownLeft(resendCooldownSeconds);
			setCode("");
		} finally {
			setResending(false);
		}
	}

	const heading = HEADINGS[intent];
	const slots = React.useMemo(
		() => Array.from({ length }, (_, i) => i),
		[length],
	);
	const cooldownLabel =
		cooldownLeft > 0 ? `Resend in ${cooldownLeft}s` : "Resend code";

	return (
		<div className={cn("flex min-h-svh items-center justify-center p-6 sm:p-10", className)}>
			<div className="w-full max-w-sm space-y-6">
				<header className="space-y-2 text-center">
					<h1 className="text-2xl font-semibold tracking-tight">{heading.title}</h1>
					<p className="text-sm text-muted-foreground">{heading.description}</p>
				</header>

				{error ? (
					<Alert variant="destructive">
						<AlertTitle>Couldn&rsquo;t verify code</AlertTitle>
						<AlertDescription>{error.message}</AlertDescription>
					</Alert>
				) : null}

				<div className="flex flex-col items-center gap-4">
					<InputOTP
						maxLength={length}
						value={code}
						onChange={setCode}
						disabled={submitting}
						aria-label="One-time code"
					>
						<InputOTPGroup>
							{slots.map((i) => (
								<InputOTPSlot key={i} index={i} />
							))}
						</InputOTPGroup>
					</InputOTP>

					{adapter.resendOtp ? (
						<Button
							type="button"
							variant="ghost"
							size="sm"
							onClick={handleResend}
							disabled={resending || cooldownLeft > 0 || submitting}
							loading={resending}
						>
							{cooldownLabel}
						</Button>
					) : null}
				</div>
			</div>
		</div>
	);
}

/**
 * The contract every Hex Core auth block consumes via its `adapter` prop.
 *
 * Hex Core does not ship session management — auth blocks are presentation-
 * only and delegate every credential, OTP, and OAuth handoff to whatever
 * the consumer wires up (better-auth, Clerk, NextAuth, Supabase Auth, a
 * custom server, …). The adapter is the single seam.
 *
 * Every method is **optional**. A block that needs `signInWithPassword` but
 * not passkeys passes an adapter implementing only the methods it needs;
 * the block surfaces a runtime error if the user hits a code path the
 * adapter doesn't implement, rather than failing to render. This lets a
 * consumer ship password-only on day one and add passkeys later without
 * forking the block source.
 *
 * A reference {@link mockAuthAdapter} lives below — used by the docs
 * showcase routes and unit tests; never ship it in production.
 */
export interface AuthAdapterResult {
	ok: boolean;
	error?: { code: string; message: string };
	redirect?: string;
}

export type AuthSocialProvider = "github" | "google" | "microsoft" | (string & {});

export type AuthOtpIntent = "sign-in" | "verify-email" | "mfa";

export interface AuthAdapter {
	signInWithPassword?(p: {
		email: string;
		password: string;
		remember: boolean;
	}): Promise<AuthAdapterResult>;
	signUpWithPassword?(p: {
		email: string;
		password: string;
		name?: string;
	}): Promise<AuthAdapterResult>;
	signInWithSocial?(p: { provider: AuthSocialProvider }): Promise<AuthAdapterResult>;
	sendMagicLink?(p: { email: string }): Promise<AuthAdapterResult>;
	verifyOtp?(p: { code: string; intent: AuthOtpIntent }): Promise<AuthAdapterResult>;
	requestPasswordReset?(p: { email: string }): Promise<AuthAdapterResult>;
	resetPassword?(p: { token: string; password: string }): Promise<AuthAdapterResult>;
	registerPasskey?(): Promise<AuthAdapterResult>;
	signInWithPasskey?(): Promise<AuthAdapterResult>;
	/**
	 * Re-send a magic link to the same address. Distinct from {@link sendMagicLink}
	 * so consumers can throttle resends and surface different analytics / error
	 * copy for the second-and-onward attempt. Used by the verify-email block.
	 */
	resendMagicLink?(p: { email: string }): Promise<AuthAdapterResult>;
	/**
	 * Re-send a one-time code for the given intent. Distinct from the initial
	 * code dispatch so consumers can throttle and log resends separately. Used
	 * by the verify-otp block.
	 */
	resendOtp?(p: { intent: AuthOtpIntent }): Promise<AuthAdapterResult>;
}

const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/**
 * In-memory mock adapter for docs showcase + tests. Every method delays
 * 400ms to simulate a network round-trip and resolves `{ ok: true }`. Do
 * not use in production — there is no validation, no persistence, and no
 * security.
 */
export const mockAuthAdapter: Required<AuthAdapter> = {
	async signInWithPassword() {
		await wait(400);
		return { ok: true, redirect: "/app" };
	},
	async signUpWithPassword() {
		await wait(400);
		return { ok: true, redirect: "/verify-email" };
	},
	async signInWithSocial({ provider }) {
		await wait(400);
		return { ok: true, redirect: `/oauth/${provider}/callback` };
	},
	async sendMagicLink() {
		await wait(400);
		return { ok: true };
	},
	async verifyOtp() {
		await wait(400);
		return { ok: true, redirect: "/app" };
	},
	async requestPasswordReset() {
		await wait(400);
		return { ok: true };
	},
	async resetPassword() {
		await wait(400);
		return { ok: true, redirect: "/sign-in" };
	},
	async registerPasskey() {
		await wait(400);
		return { ok: true };
	},
	async signInWithPasskey() {
		await wait(400);
		return { ok: true, redirect: "/app" };
	},
	async resendMagicLink() {
		await wait(400);
		return { ok: true };
	},
	async resendOtp() {
		await wait(400);
		return { ok: true };
	},
};

import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";

const alertVariants = cva(
	[
		"relative w-full rounded-lg border px-[var(--space-4,1rem)] py-[var(--space-3,0.75rem)] text-sm",
		"transition-all duration-[var(--duration-normal,200ms)] ease-out",
		"[&>svg]:absolute [&>svg]:left-4 [&>svg]:top-4 [&>svg]:h-4 [&>svg]:w-4 [&>svg]:text-foreground",
		"[&>svg~*]:pl-7 [&>svg+div]:translate-y-[-3px]",
	].join(" "),
	{
		variants: {
			variant: {
				default: "border-foreground/[0.08] bg-background text-foreground",
				destructive:
					"border-destructive/50 text-destructive [&>svg]:text-destructive bg-destructive/5",
			},
		},
		defaultVariants: { variant: "default" },
	},
);

/** An inline notification banner for important messages. */
const Alert = React.forwardRef<
	HTMLDivElement,
	React.HTMLAttributes<HTMLDivElement> & VariantProps<typeof alertVariants>
>(({ className, variant, ...props }, ref) => (
	<div
		ref={ref}
		role="alert"
		className={cn(alertVariants({ variant }), className)}
		{...props}
	/>
));
Alert.displayName = "Alert";

/** The alert title heading. */
const AlertTitle = React.forwardRef<
	HTMLHeadingElement,
	React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => (
	<h5
		ref={ref}
		className={cn("mb-[var(--space-1,0.25rem)] font-medium leading-none tracking-tight", className)}
		{...props}
	/>
));
AlertTitle.displayName = "AlertTitle";

/** The alert description. Renders a div so paragraph children can be styled via [&_p]. */
const AlertDescription = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
	({ className, ...props }, ref) => (
		<div ref={ref} className={cn("text-sm [&_p]:leading-relaxed", className)} {...props} />
	),
);
AlertDescription.displayName = "AlertDescription";

export { Alert, AlertTitle, AlertDescription, alertVariants };

"use client";

import { OTPInput, OTPInputContext } from "input-otp";
import * as React from "react";
import { cn } from "../../lib/utils.js";

/** Props for the root InputOTP component (mirrors input-otp's OTPInput). */
type InputOTPProps = React.ComponentPropsWithoutRef<typeof OTPInput>;

/** Root OTP input. Wraps input-otp's OTPInput and exposes slot context to children. */
const InputOTP = React.forwardRef<React.ComponentRef<typeof OTPInput>, InputOTPProps>(
	({ className, containerClassName, ...props }, ref) => (
	<OTPInput
		ref={ref}
		containerClassName={cn(
			"flex items-center gap-[var(--gap-sm,0.5rem)] has-[:disabled]:opacity-50",
			containerClassName,
		)}
		className={cn(
			"disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50",
			className,
		)}
		{...props}
	/>
));
InputOTP.displayName = "InputOTP";

/** Groups slots together; place between runs of slots to add visual dividers. */
const InputOTPGroup = React.forwardRef<
	React.ComponentRef<"div">,
	React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => (
	<div ref={ref} className={cn("flex items-center", className)} {...props} />
));
InputOTPGroup.displayName = "InputOTPGroup";

interface InputOTPSlotProps extends React.ComponentPropsWithoutRef<"div"> {
	/** Index of the slot in the underlying OTP value. */
	index: number;
}

/** A single character slot. Reads its state from OTPInputContext. */
const InputOTPSlot = React.forwardRef<HTMLDivElement, InputOTPSlotProps>(
	({ index, className, ...props }, ref) => {
		const inputOTPContext = React.useContext(OTPInputContext);
		const slot = inputOTPContext.slots[index];
		const char = slot?.char ?? null;
		const hasFakeCaret = slot?.hasFakeCaret ?? false;
		const isActive = slot?.isActive ?? false;

		return (
			<div
				ref={ref}
				className={cn(
					"relative flex h-[var(--control-height-md,2.5rem)] w-[var(--control-height-md,2.5rem)] items-center justify-center border-y border-r border-input text-sm transition-all duration-[var(--duration-normal,200ms)] ease-out",
					"inset-ring-1 inset-ring-foreground/[0.06]",
					"first:rounded-l-md first:border-l last:rounded-r-md",
					isActive && "z-10 ring-2 ring-ring ring-offset-2 ring-offset-background",
					className,
				)}
				{...props}
			>
				{char}
				{hasFakeCaret && (
					<div className="pointer-events-none absolute inset-0 flex items-center justify-center">
						<div className="h-4 w-px animate-pulse bg-foreground duration-1000" />
					</div>
				)}
			</div>
		);
	},
);
InputOTPSlot.displayName = "InputOTPSlot";

/** Visual separator between slot groups (a bullet by default). */
const InputOTPSeparator = React.forwardRef<
	React.ComponentRef<"div">,
	React.ComponentPropsWithoutRef<"div">
>(({ ...props }, ref) => (
	<div ref={ref} role="separator" {...props}>
		<svg
			xmlns="http://www.w3.org/2000/svg"
			viewBox="0 0 24 24"
			fill="currentColor"
			className="h-2 w-2 text-muted-foreground"
			aria-hidden="true"
		>
			<circle cx="12" cy="12" r="6" />
		</svg>
	</div>
));
InputOTPSeparator.displayName = "InputOTPSeparator";

export { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator };
export type { InputOTPProps };

"use client";

import { Slot } from "@radix-ui/react-slot";
import * as React from "react";
import { cn } from "../../lib/utils.js";
import { type ButtonVariantsProps, buttonVariants } from "./button-variants.js";

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		ButtonVariantsProps {
	asChild?: boolean;
	loading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	(
		{ className, variant, size, asChild = false, loading = false, children, disabled, ...props },
		ref,
	) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				disabled={disabled || loading}
				aria-busy={loading || undefined}
				{...props}
			>
				{loading ? (
					<>
						<svg
							className="animate-spin h-4 w-4"
							xmlns="http://www.w3.org/2000/svg"
							fill="none"
							viewBox="0 0 24 24"
							aria-hidden="true"
						>
							<circle
								className="opacity-25"
								cx="12"
								cy="12"
								r="10"
								stroke="currentColor"
								strokeWidth="4"
							/>
							<path
								className="opacity-75"
								fill="currentColor"
								d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
							/>
						</svg>
						{children}
					</>
				) : (
					children
				)}
			</Comp>
		);
	},
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { type VariantProps, cva } from "class-variance-authority";

/**
 * CVA variants for the Button component.
 *
 * Lives in its own module so RSC-safe consumers (`Pagination`, future
 * link-styled buttons in static layouts) can import variants without
 * pulling in the full `Button` runtime — `Button` itself is client-only
 * because of `Slot` + `forwardRef` + the loading spinner. Splitting the
 * variants out keeps `dist/pagination.js` free of `@radix-ui/react-slot`.
 */
export const buttonVariants = cva(
	[
		"inline-flex items-center justify-center gap-[var(--gap-sm,0.5rem)] whitespace-nowrap rounded-md text-sm font-medium",
		"transition-all duration-[var(--duration-normal,200ms)] ease-out",
		"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
		"disabled:pointer-events-none disabled:opacity-50",
		"active:scale-[0.98]",
		"[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
	].join(" "),
	{
		variants: {
			variant: {
				default: [
					"bg-primary text-primary-foreground",
					"shadow-sm shadow-primary/20",
					"hover:bg-primary/90 hover:shadow-md hover:shadow-primary/25",
				].join(" "),
				destructive: [
					"bg-destructive text-destructive-foreground",
					"shadow-sm shadow-destructive/20",
					"hover:bg-destructive/90 hover:shadow-md hover:shadow-destructive/25",
				].join(" "),
				outline: [
					"border border-input bg-background",
					"shadow-sm inset-ring-1 inset-ring-foreground/[0.06]",
					"hover:bg-accent hover:text-accent-foreground hover:shadow-md hover:inset-ring-foreground/12",
				].join(" "),
				secondary: [
					"bg-secondary text-secondary-foreground",
					"shadow-sm inset-ring-1 inset-ring-foreground/[0.08]",
					"hover:bg-secondary/80 hover:shadow-md hover:inset-ring-foreground/15",
				].join(" "),
				ghost: "hover:bg-accent hover:text-accent-foreground",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default:
					"h-[var(--control-height-md,2.5rem)] px-[var(--space-4,1rem)] py-[var(--space-2,0.5rem)]",
				sm: "h-[var(--control-height-sm,2.25rem)] rounded-md px-[var(--space-3,0.75rem)]",
				lg: "h-[var(--control-height-lg,2.75rem)] rounded-md px-[var(--space-8,2rem)] text-base",
				icon: "h-[var(--control-height-md,2.5rem)] w-[var(--control-height-md,2.5rem)]",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	},
);

export type ButtonVariantsProps = VariantProps<typeof buttonVariants>;

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}
